content.text:
        seen_ids.add(tid)
        if type(src) is not str or not TRACEID_RE.fullmatch(src):
            schema_fail()
        rows = trace['rows']
        if type(rows) is not list:
            schema_fail()
        parsed = []
        for row in rows:
            if type(row) is not dict or set(row.keys()) != {'t', 'values'}:
                schema_fail()
            t = row['t']
            if type(t) is not int or not (INT32_MIN <= t <= INT32_MAX):
                schema_fail()
            parsed.append((t, check_row(row['values'], types, domains)))
        row_counter[0] += len(parsed)
        parsed.sort(key=lambda item: item[0])
        prev = None
        times = []
        values = []
        for t, vals in parsed:
            if t == prev:
                schema_fail()
            prev = t
            times.append(t)
            values.append(vals)
        out.append((tid, src, values, times))
    return out


def count_contexts(traces, k):
    total = 0
    for _tid, _src, values, _times in traces:
        n = len(values)
        if n >= k:
            total += n - k + 1
    return total


def build_contexts(traces, k, want_meta):
    ctxs = []
    meta = []
    for tid, src, values, times in traces:
        n = len(values)
        if n < k:
            continue
        for i in range(n - k + 1):
            ctxs.append(tuple(values[i:i + k]))
            if want_meta:
                meta.append((tid, times[i + k - 1], src))
    return ctxs, meta


