_BIT_TABLES = [bytes(1 if (v >> p) & 1 else 0 for v in range(256))
               for p in range(8)]


def column_counts(items, D):
    """items: list of (mask, weight) with mask < 2**D.

    Returns a list of D integers: for each bit position d, the total weight of
    items whose mask has bit d set.
    """
    res = [0] * D
    if D == 0 or not items:
        return res
    nb = (D + 7) >> 3
    tables = _BIT_TABLES
    from_bytes = int.from_bytes
    parts = []
    for mask, wt in items:
        while wt > 0:
            take = 255 if wt > 255 else wt
            parts.append((mask, take))
            wt -= take
    items = parts
    chunk = []
    cw = 0

    def flush(entries):
        accs = [0] * 8
        for mask, wt in entries:
            data = mask.to_bytes(nb, 'little')
            if wt == 1:
                for p in range(8):
                    accs[p] += from_bytes(data.translate(tables[p]), 'little')
            else:
                for p in range(8):
                    accs[p] += from_bytes(data.translate(tables[p]), 'little') * wt
        for p in range(8):
            acc = accs[p]
            if not acc:
                continue
            data = acc.to_bytes(nb, 'little')
            for j in range(nb):
                v = data[j]
                if v:
                    idx = (j << 3) | p
                    if idx < D:
                        res[idx] += v

    for mask, wt in items:
        if cw + wt > 255 and chunk:
            flush(chunk)
            chunk = []
            cw = 0
        chunk.append((mask, wt))
        cw += wt
    if chunk:
        flush(chunk)
    return res


